package com.crm.invoice;
import com.crm.invoice.client.InvoiceSourceClient;import com.fasterxml.jackson.databind.*;import org.junit.jupiter.api.*;import org.springframework.cloud.client.discovery.DiscoveryClient;import org.springframework.web.server.ResponseStatusException;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class InvoiceSourceContractTest {
 InvoiceSourceClient source;ObjectMapper mapper=new ObjectMapper();JsonNode valid;
 @BeforeEach void setup()throws Exception{source=spy(new InvoiceSourceClient(mock(DiscoveryClient.class)));valid=mapper.readTree("{\"id\":\"11\",\"customerId\":\"101\",\"currency\":\"TND\",\"serviceName\":\"Consulting\",\"sourceTimeId\":\"21\",\"hours\":\"2.50\",\"rate\":\"12.34\",\"amount\":\"30.85\",\"immutable\":true}");}
 void response(JsonNode row){doReturn(row).when(source).read(anyString(),anyString(),anyMap(),anyString());}
 @Test void exactTextIdentifiersAndCapturedAmountsArePreserved(){response(valid);assertEquals("30.85",source.get(11,"Bearer synthetic").amount());verify(source).read("fees-service","/api/fees/billing-candidates/11",Map.of(),"Bearer synthetic");}
 @Test void mutableNumericOrMismatchedSnapshotsFailClosed(){for(String json:List.of("{\"immutable\":false}",valid.toString().replace("\"11\"","11"),valid.toString().replace("30.85","30.86"),valid.toString().replace("\"11\"","\"12\""),valid.toString().replace("2.50","2.501"))){try{response(mapper.readTree(json));}catch(Exception e){throw new RuntimeException(e);}assertEquals(502,assertThrows(ResponseStatusException.class,()->source.get(11,"Bearer synthetic")).getStatusCode().value());}}
 @Test void candidatePageRequiresMatchingCustomerCurrencyAndBoundedMetadata()throws Exception{response(mapper.readTree("{\"content\":["+valid+"],\"number\":0,\"totalPages\":1,\"totalElements\":1}"));assertEquals(1,source.list("101","TND",0,"Bearer synthetic").content().size());assertThrows(ResponseStatusException.class,()->source.list("102","TND",0,"Bearer synthetic"));response(mapper.readTree("{\"content\":[],\"number\":0,\"totalPages\":99999999999999999999,\"totalElements\":1}"));assertThrows(ResponseStatusException.class,()->source.list("101","TND",0,"Bearer synthetic"));}
 @Test void activeCustomerProofIsMandatory()throws Exception{response(mapper.readTree("{\"id\":101,\"archived\":false,\"contactType\":\"CUSTOMER\"}"));source.customer("101","Bearer synthetic");response(mapper.readTree("{\"id\":101,\"archived\":true,\"contactType\":\"CUSTOMER\"}"));assertEquals(409,assertThrows(ResponseStatusException.class,()->source.customer("101","Bearer synthetic")).getStatusCode().value());response(mapper.readTree("{\"id\":101.0}"));assertEquals(502,assertThrows(ResponseStatusException.class,()->source.customer("101","Bearer synthetic")).getStatusCode().value());}
 @Test void missingBearerAndDiscoveryHaveNoAnonymousFallback(){var client=new InvoiceSourceClient(mock(DiscoveryClient.class));assertEquals(401,assertThrows(ResponseStatusException.class,()->client.get(11,null)).getStatusCode().value());assertEquals(503,assertThrows(ResponseStatusException.class,()->client.get(11,"Bearer synthetic")).getStatusCode().value());}
}
